<?php
require_once '../config/app.php'; $pageTitle = 'Admin dashboard'; $pdo = db(); $election = current_election(); $voters = $pdo->query('SELECT COUNT(*) FROM voters')->fetchColumn(); $ballots = $pdo->prepare('SELECT COUNT(*) FROM ballots WHERE election_id = ?'); $ballots->execute([$election['id'] ?? 0]); $ballots = $ballots->fetchColumn(); $events = $pdo->query('SELECT event_type, created_at FROM audit_logs ORDER BY id DESC LIMIT 6')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?></title><link rel="stylesheet" href="../assets/style.css"></head><body><header class="topbar"><a class="brand" href="../index.php"><span class="brand-mark">CB</span><span>Civic Ballot / Admin</span></a><nav><a href="../results.php">Public results</a></nav></header><main class="shell"><div class="eyebrow">Operations console</div><h1>Election control room</h1><div class="admin-nav"><a href="index.php">Overview</a><a href="candidates.php">Candidates</a><a href="voters.php">Voter register</a><a href="audit-log.php">Audit log</a></div><div class="grid"><div class="panel"><div class="stat"><?= (int) $voters ?></div><div class="label">Eligible voters</div></div><div class="panel"><div class="stat"><?= (int) $ballots ?></div><div class="label">Anonymous ballots</div></div><div class="panel"><div class="stat"><?= $voters ? round($ballots / $voters * 100) : 0 ?>%</div><div class="label">Turnout</div></div></div><section style="margin-top:48px"><div class="section-heading"><h2>Active election</h2><span class="label">Aggregate view only</span></div><div class="panel"><h3><?= e($election['title'] ?? 'No open election') ?></h3><p><?= e($election['description'] ?? '') ?></p><p class="party">Identity records and ballot choices cannot be joined from this dashboard.</p></div></section><section style="margin-top:48px"><div class="section-heading"><h2>Recent events</h2></div><div class="panel"><?php foreach ($events as $event): ?><div class="results-row"><strong><?= e($event['event_type']) ?></strong><span><?= e($event['created_at']) ?></span><span class="party">recorded</span></div><?php endforeach; ?></div></section></main></body></html>